INSERT INTO `concert` (`c_id`, `c_organization_id`, `name`, `artist`, `venue`, `event_datetime`, `description`, `phone`, `email`, `facebook`, `line`, `poster_path`, `banner_path`, `seat_map_image_path`, `sale_start_datetime`, `sale_end_datetime`, `max_ticket_per_order`, `status`, `concert_code`, `deleted_at`, `created_at`) VALUES
(1, 1, 'Rock Night 2026', 'Bodyslam', 'BCC Hall, Bangkok', '2026-11-14 18:00:00', 'คอนเสิร์ตร็อกสุดมันส์ประจำปี กับวงบอดี้แสลมและเพื่อนศิลปินรับเชิญ พร้อมโซนที่นั่งและโซนยืน', '02-669-9000', 'contact@gmm-grammy.example', 'GMM Grammy Official', '@gmmgrammy', NULL, NULL, 'seat-maps/demo-rock-night-2026.png', '2026-09-15 10:00:00', '2026-11-13 23:59:59', 4, 'ON_SALE', 'C0001', NULL, NOW()),
(2, 2, 'Pop Star Live 2026', 'Bird Thongchai', 'Impact Arena, Muang Thong Thani', '2026-12-12 19:00:00', 'ป็อปคอนเสิร์ตใหญ่ส่งท้ายปี ผสมโซนที่นั่งและโซนยืนใกล้เวที', '02-612-9999', 'contact@bec-tero.example', 'BEC-Tero Entertainment', '@bectero', NULL, NULL, 'seat-maps/demo-pop-star-live-2026.png', '2026-10-01 10:00:00', '2026-12-11 23:59:59', 6, 'ON_SALE', 'C0002', NULL, NOW()),
(3, 1, 'Acoustic Evening', 'Sunset Strings', 'Thailand Cultural Centre', '2026-11-21 19:30:00', 'ค่ำคืนอะคูสติกเบา ๆ ใจกลางเมือง ที่นั่งทั้งหมดระบุหมายเลข', '02-669-9000', 'contact@gmm-grammy.example', 'GMM Grammy Official', '@gmmgrammy', NULL, NULL, 'seat-maps/demo-acoustic-evening.png', '2026-09-20 10:00:00', '2026-11-20 23:59:59', 4, 'ON_SALE', 'C0003', NULL, NOW()),
(4, 3, 'EDM Countdown 2027', 'Skyline DJs', 'Siam Paragon Open Air', '2026-12-31 20:00:00', 'ปาร์ตี้ EDM ส่งท้ายปีเก่า ยืนเต้นได้ทั้งคืน (โซนยืนทั้งหมด)', '02-111-2233', 'hello@movelive.example', 'Move Live Thailand', '@movelive', NULL, NULL, 'seat-maps/demo-edm-countdown.png', '2026-10-10 10:00:00', '2026-12-30 23:59:59', 6, 'ON_SALE', 'C0004', NULL, NOW()),
(5, 3, 'Jazz Under the Stars', 'Blue Note Quartet', 'Lumpini Park Amphitheatre', '2026-11-28 19:00:00', 'แจ๊สใต้แสงดาว ตั๋วเหลือน้อยมาก ใช้ดูสถานะป้ายที่นั่งใกล้เต็ม', '02-111-2233', 'hello@movelive.example', 'Move Live Thailand', '@movelive', NULL, NULL, 'seat-maps/demo-jazz-under-the-stars.png', '2026-09-25 10:00:00', '2026-11-27 23:59:59', 4, 'ON_SALE', 'C0005', NULL, NOW()),
(6, 2, 'K-Wave Fan Fest', 'Starlight Seoul', 'Rajamangala National Stadium', '2026-12-05 17:00:00', 'แฟนมีตติ้งศิลปินเกาหลี บัตรหมดเกลี้ยงแล้ว ใช้ดูสถานะขายหมด', '02-612-9999', 'contact@bec-tero.example', 'BEC-Tero Entertainment', '@bectero', NULL, NULL, 'seat-maps/demo-k-wave-fan-fest.png', '2026-08-20 10:00:00', '2026-12-04 23:59:59', 4, 'SOLD_OUT', 'C0006', NULL, NOW()),
(7, 1, 'Summer Splash 2027', 'Wave Riders', 'Pattaya Beach Stage', '2027-03-20 17:00:00', 'เทศกาลดนตรีริมชายหาดรับซัมเมอร์ เปิดขายเร็ว ๆ นี้', '02-669-9000', 'contact@gmm-grammy.example', 'GMM Grammy Official', '@gmmgrammy', NULL, NULL, 'seat-maps/demo-summer-splash-2027.png', '2026-12-01 10:00:00', '2027-03-19 23:59:59', 6, 'SCHEDULED', 'C0007', NULL, NOW()),
(8, 2, 'Symphony Pop Night', 'Bangkok Orchestra', 'Prince Mahidol Hall', '2027-01-23 19:00:00', 'ซิมโฟนีออร์เคสตราเล่นเพลงป็อป เปิดจองเร็ว ๆ นี้', '02-612-9999', 'contact@bec-tero.example', 'BEC-Tero Entertainment', '@bectero', NULL, NULL, 'seat-maps/demo-symphony-pop-night.png', '2026-11-15 10:00:00', '2027-01-22 23:59:59', 4, 'SCHEDULED', 'C0008', NULL, NOW()),
(9, 1, 'Luk Thung Grand Concert', 'Pumpuang Legacy', 'Thunder Dome, Muang Thong Thani', '2026-12-19 18:00:00', 'ลูกทุ่งแกรนด์คอนเสิร์ต รวมศิลปินชื่อดัง ทั้งโซนนั่งและโซนยืน', '02-669-9000', 'contact@gmm-grammy.example', 'GMM Grammy Official', '@gmmgrammy', NULL, NULL, 'seat-maps/demo-luk-thung-grand-concert.png', '2026-10-05 10:00:00', '2026-12-18 23:59:59', 6, 'ON_SALE', 'C0009', NULL, NOW()),
(10, 3, 'Hip-Hop Takeover', 'Urban Flow', 'Union Hall, Bangkok', '2027-02-14 20:00:00', 'คอนเสิร์ตแบบร่าง ยังไม่เผยแพร่ (เห็นเฉพาะฝั่งผู้จัด ไม่ขึ้นหน้าเว็บ)', '02-111-2233', 'hello@movelive.example', 'Move Live Thailand', '@movelive', NULL, NULL, 'seat-maps/demo-hip-hop-takeover.png', '2027-01-05 10:00:00', '2027-02-13 23:59:59', 4, 'DRAFT', 'C0010', NULL, NOW()),
(11, 3, 'Indie Garden Fest', 'Paper Kites TH', 'Benjakitti Forest Park', '2026-11-29 15:00:00', 'เทศกาลอินดี้กลางสวน นั่งปิกนิกฟังเพลงสบาย ๆ', '02-111-2233', 'hello@movelive.example', 'Move Live Thailand', '@movelive', NULL, NULL, 'seat-maps/demo-indie-garden-fest.png', '2026-09-28 10:00:00', '2026-11-28 23:59:59', 6, 'ON_SALE', 'C0011', NULL, NOW()),
(12, 1, 'Throwback 90s Reunion', 'The Classic Band', 'Impact Challenger Hall', '2026-12-26 18:30:00', 'รวมตัวศิลปินยุค 90 ร้องเพลงฮิตตลอดกาล', '02-669-9000', 'contact@gmm-grammy.example', 'GMM Grammy Official', '@gmmgrammy', NULL, NULL, 'seat-maps/demo-throwback-90s-reunion.png', '2026-10-12 10:00:00', '2026-12-25 23:59:59', 4, 'ON_SALE', 'C0012', NULL, NOW()),
(13, 2, 'Midnight Soul', 'Velvet Voices', 'Siam Pavalai Royal Grand Theatre', '2026-11-07 20:00:00', 'ค่ำคืนโซลและอาร์แอนด์บี บรรยากาศอบอุ่น ที่นั่งเริ่มเหลือน้อย', '02-612-9999', 'contact@bec-tero.example', 'BEC-Tero Entertainment', '@bectero', NULL, NULL, 'seat-maps/demo-midnight-soul.png', '2026-09-10 10:00:00', '2026-11-06 23:59:59', 4, 'ON_SALE', 'C0013', NULL, NOW()),
(14, 3, 'Anime Music Festival', 'Various Artists', 'Bitec Hall 99', '2027-01-09 12:00:00', 'เทศกาลดนตรีอนิเมะ รวมศิลปินและคอสเพลย์ เปิดขายเร็ว ๆ นี้', '02-111-2233', 'hello@movelive.example', 'Move Live Thailand', '@movelive', NULL, NULL, 'seat-maps/demo-anime-music-festival.png', '2026-11-20 10:00:00', '2027-01-08 23:59:59', 6, 'SCHEDULED', 'C0014', NULL, NOW()),
(15, 1, 'Thai Folk Night', 'Sala Kham Trio', 'Chiang Mai Convention Centre', '2026-12-06 19:00:00', 'ค่ำคืนเพลงโฟล์กล้านนา ที่นั่งทั้งหมด เหมาะกับการทดสอบจองหลายที่นั่งติดกัน', '02-669-9000', 'contact@gmm-grammy.example', 'GMM Grammy Official', '@gmmgrammy', NULL, NULL, 'seat-maps/demo-thai-folk-night.png', '2026-10-08 10:00:00', '2026-12-05 23:59:59', 4, 'ON_SALE', 'C0015', NULL, NOW()),
(16, 1, 'Grand Mega Concert 2027', 'All Star Alliance', 'Rajamangala National Stadium', '2027-02-27 17:00:00', 'มหกรรมคอนเสิร์ตสเกลใหญ่สุด ครบทุกรูปแบบ มีทั้งโซนที่นั่งแถวยาว 16-32 ที่นั่งต่อแถว และโซนยืนหลายราคา', '02-669-9000', 'contact@gmm-grammy.example', 'GMM Grammy Official', '@gmmgrammy', NULL, NULL, 'seat-maps/demo-grand-mega-concert.png', '2026-10-15 10:00:00', '2027-02-26 23:59:59', 4, 'ON_SALE', 'C0016', NULL, NOW());
